<?php $secPanel=$secPanel??'admin'; ?>
<style>#security-settings [hidden]{display:none!important}</style>
<section id="security-settings" data-panel="<?=e($secPanel)?>" data-endpoint="<?=e(url($secPanel.'/security-api.php'))?>" class="my-7 rounded-3xl border border-neutral-200 bg-white p-5 sm:p-7">
<h2 class="text-xl font-black">أمان تسجيل الدخول</h2><p class="mt-2 text-sm leading-7 text-neutral-500">الجلسة تنتهي بعد الخمول حتى عند اختيار تذكرني. ملفات جلسة المتصفح قد تستعاد عند إعادة فتحه.</p>
<div id="sec-normal"><div class="mt-5 rounded-2xl bg-neutral-50 p-4"><h3 id="sec-state" class="font-bold"></h3><p class="mt-1 text-xs leading-6 text-neutral-500">اختياري لكل حساب. التفعيل أو الإلغاء ينهي جلسات هذا الحساب.</p><p id="sec-key-note" class="mt-3 text-sm text-amber-700" hidden>يحتاج الخادم إلى مفتاح تشفير ثابت قبل التفعيل.</p><label class="mt-4 block text-sm font-bold">كلمة المرور الحالية<input id="sec-password" type="password" autocomplete="current-password" dir="ltr" class="mt-2 w-full rounded-xl border bg-white p-3"></label><div id="sec-setup" class="mt-4 rounded-xl border bg-white p-4" hidden><p class="text-sm leading-7">في التطبيق اختر إضافة حساب ثم إدخال مفتاح الإعداد يدويا. الحساب: IStore <?=e($secPanel)?></p><code id="sec-secret" class="my-3 block break-all rounded bg-neutral-100 p-3 text-sm" dir="ltr"></code><p class="text-xs text-neutral-500">TOTP · SHA1 · 6 أرقام · 30 ثانية</p></div><label id="sec-code-label" class="mt-4 block text-sm font-bold" hidden>رمز التحقق أو الاسترداد<input id="sec-code" autocomplete="one-time-code" dir="ltr" class="mt-2 w-full rounded-xl border bg-white p-3"></label><button id="sec-action" type="button" class="mt-4 rounded-full bg-black px-6 py-3 text-sm font-bold text-white"></button></div>
<?php if($secPanel==='control'):?><h3 class="mt-6 font-bold">سياسة الدخول، للوحتين</h3><div class="mt-4 grid gap-4 sm:grid-cols-2"><?php foreach([['failures','المحاولات الفاشلة (3–20)',3,20],['lockMinutes','مدة القفل بالدقائق (1–120)',1,120],['idleMinutes','الخمول بالدقائق (5–240)',5,240],['rememberDays','تذكرني بالأيام (1–30)',1,30]] as [$key,$label,$min,$max]):?><label class="text-sm font-bold"><?=e($label)?><input id="sec-<?=e($key)?>" type="number" min="<?=$min?>" max="<?=$max?>" class="mt-2 w-full rounded-xl border p-3"></label><?php endforeach;?></div><p class="mt-3 text-xs text-neutral-500">كلمة المرور الحالية مطلوبة لحفظ السياسة. سجل الدخول يحتفظ بآخر 90 يوما.</p><button id="sec-save" type="button" class="mt-4 rounded-full border px-6 py-3 text-sm font-bold">حفظ سياسة الدخول</button><h3 class="mb-3 mt-7 font-bold">آخر 100 عملية دخول</h3><div id="sec-activity" class="max-h-96 space-y-2 overflow-auto"></div><?php endif;?></div>
<div id="sec-recovery" hidden><p class="my-4 rounded-xl bg-emerald-50 p-4 text-sm">تم التفعيل. احفظ رموز الاسترداد الآن، ثم سجل الدخول مجددا.</p><p class="text-sm font-bold">رموز استرداد، كل رمز يستخدم مرة واحدة. لن تظهر مرة أخرى.</p><pre id="sec-recovery-codes" class="my-4 rounded-xl bg-neutral-100 p-4 text-sm" dir="ltr"></pre><button type="button" id="sec-download" class="rounded-full border px-5 py-2">تنزيل رموز الاسترداد</button><a class="mr-4 text-sm underline" href="<?=e(url($secPanel.'/login.php'))?>">حفظت الرموز، تسجيل الدخول</a></div><p id="sec-message" role="status" class="mt-4 rounded-xl bg-amber-50 p-3 text-sm" hidden></p></section>
<script>
(()=>{const root=document.getElementById('security-settings'),ep=root.dataset.endpoint,panel=root.dataset.panel;let status,setup=false,recovery=[];const $=id=>document.getElementById('sec-'+id);async function load(){const r=await fetch(ep);if(!r.ok)return;status=await r.json();$('state').textContent='تطبيق المصادقة: '+(status.enabled?'مفعل لهذا الحساب':'غير مفعل لهذا الحساب');$('key-note').hidden=status.ready;$('action').disabled=!status.ready;$('action').textContent=status.enabled?'إلغاء التحقق بخطوتين':setup?'تأكيد التفعيل':'إعداد تطبيق المصادقة';$('code-label').hidden=!setup&&!status.enabled;if(panel==='control'){for(const k of ['failures','lockMinutes','idleMinutes','rememberDays'])$(k).value=status.config[k];$('activity').replaceChildren();for(const row of status.activity){const d=document.createElement('div');d.className='rounded-xl border p-3 text-xs leading-6';const title=document.createElement('div');title.className='font-bold';const labels={success:'دخول ناجح',failed:'بيانات غير صحيحة',totp_failed:'رمز تحقق غير صحيح',totp_enabled:'تفعيل المصادقة',totp_disabled:'إلغاء المصادقة',policy_changed:'تغيير السياسة'};title.textContent=row.username+' · '+row.panel+' · '+new Date(Number(row.created_at)).toLocaleString('ar-LY',{timeZone:'Africa/Tripoli'})+' · '+(labels[row.result]||row.result);const device=document.createElement('p');device.dir='ltr';device.className='break-all text-neutral-500';device.textContent=row.device;d.append(title,device);$('activity').append(d);}}}
async function action(action){if(!$('password').value){$('message').hidden=false;$('message').textContent='أدخل كلمة المرور الحالية';return;}$('action').disabled=true;const data={action,csrf:status.csrf,password:$('password').value,code:$('code').value};if(action==='config')for(const k of ['failures','lockMinutes','idleMinutes','rememberDays'])data[k]=Number($(k).value);try{const r=await fetch(ep,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();if(!r.ok)throw Error(d.error||'حدث خطأ');if(action==='begin'){setup=true;$('setup').hidden=false;$('secret').textContent=d.secret;$('code-label').hidden=false;$('action').textContent='تأكيد التفعيل';}else if(d.recovery_codes){recovery=d.recovery_codes;$('normal').hidden=true;$('recovery').hidden=false;$('recovery-codes').textContent=recovery.join('\n');$('password').value='';$('code').value='';}else if(d.relogin)location.href=panel==='control'?'login.php':'login.php';else{$('message').hidden=false;$('message').textContent='تم الحفظ';$('password').value='';await load();}}catch(e){$('message').hidden=false;$('message').textContent=e.message;}finally{$('action').disabled=false;}}
$('action').onclick=()=>action(status.enabled?'disable':setup?'confirm':'begin');if($('save'))$('save').onclick=()=>action('config');$('download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([recovery.join('\n')],{type:'text/plain'}));a.download='istore-recovery-codes.txt';a.click();URL.revokeObjectURL(a.href);};load();})();
</script>
